```ts next-bound-frontend/src/app/administration/services/adm-user.service.ts
import { HttpClient } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";
import { User, userStore } from "src/app/store/userStore";
import { environment } from "src/environments/environment.development";

@Injectable({
  providedIn: "root",
})
export class AdmUserService {
  constructor() {}

  private http = inject(HttpClient);
  private userStore = inject(userStore);

  fetchUsers() {
    this.http.get<User[]>(`${environment.apiUrl}/user`).subscribe({
      next: (response) => {
        this.userStore.setUsers(response);
      },
    });
  }

  addUser(user: User) {
    this.http.post<User>(`${environment.apiUrl}/user`, user).subscribe({
      next: (response) => {
        this.userStore.addUser(response);
      },
    });
  }

  updateUser(user: User) {
    this.http
      .put<User>(`${environment.apiUrl}/user/${user.id}`, user)
      .subscribe({
        next: (response) => {
          this.userStore.updateUser(response);
        },
      });
  }

  deleteUser(user: User) {
    this.http.delete(`${environment.apiUrl}/user/${user.id}`).subscribe({
      next: () => {
        this.userStore.removeUser(user.id);
      },
    });
  }
}
